    "owner_agent": "AlgebraWise",
    "tasks": {
        "FindLoserVotes": "Calculate the number of votes the loser received."
    },
    "orders": [
        {
            "condition": "success",
            "from": null,
            "to": "FindLoserVotes"
        }
    ],
